"""de — prophets_c."""

T = {
"prophets_151": ("Wovon durften Adam und seine Frau sich im Garten nicht nähern?", ["Einem Baum", "Einem Fluss", "Einem Tor", "Einem Berg"], "Allah erlaubte ihnen, nach Belieben zu essen, nur einem einzigen Baum durften sie sich nicht nähern."),
"prophets_152": ("Was empfing Adam laut Koran von seinem Herrn nach seinem Fehltritt?", ["Worte (der Reue), und Allah nahm seine Reue an", "Reichtum", "Ein Königreich", "Ein Buch"], "«Da empfing Adam von seinem Herrn Worte, und Er nahm seine Reue an»."),
"prophets_153": ("Mit wem vergleicht der Koran 'Isa hinsichtlich seiner Erschaffung?", ["Mit Adam, aus Erde erschaffen", "Mit Nuh (Noah)", "Mit Ibrahim (Abraham)", "Mit Yahya (Johannes)"], "«Das Gleichnis 'Isas ist bei Allah wie das Gleichnis Adams: Er erschuf ihn aus Erde, dann sprach Er zu ihm “Sei!”, und er war»."),
"prophets_154": ("Von welchem Propheten sagt der Koran, er sei wahrhaftig gewesen und Allah habe ihn an einen hohen Ort erhoben?", ["Idris (Henoch)", "Ilyas (Elia)", "Dhul-Kifl", "Al-Yasa' (Elisa)"], "«Und gedenke im Buch des Idris: er war wahrhaftig, ein Prophet; und Wir erhoben ihn an einen hohen Ort»."),
"prophets_155": ("Was sagte Nuh, als die Seinen die Arche bestiegen?", ["«Im Namen Allahs sei ihre Fahrt und ihre Landung»", "«Fürchtet das Meer nicht»", "«Nehmt euren Proviant»", "«Wartet die Nacht ab»"], "«Steigt in sie ein: im Namen Allahs sei ihre Fahrt und ihre Landung»."),
"prophets_156": ("Was erbat der Prophet Nuh in der Sure Nuh von seinem Herrn bezüglich der Ungläubigen?", ["Keinen von ihnen auf der Erde zu lassen", "Sie reich zu machen", "Ihnen ein weiteres Jahr zu geben", "Sie zu verbannen"], "«Mein Herr, lass auf der Erde keinen der Ungläubigen als Bewohner zurück»."),
"prophets_157": ("Wie viele von jeder Art sollte Nuh in die Arche nehmen?", ["Ein Paar", "Drei", "Zehn", "Nur eines"], "Allah befahl ihm, von jeder Art ein Paar hineinzuladen, dazu seine Familie."),
"prophets_158": ("Hud erinnerte 'Ad daran, dass Allah sie zu Nachfolgern gemacht habe – nach welchem Volk?", ["Nach dem Volk Nuhs (Noahs)", "Nach dem Volk Luts (Lots)", "Nach dem Volk Musas (Moses)", "Nach dem Volk von Saba"], "«Gedenkt, als Er euch zu Nachfolgern nach dem Volk Nuhs machte und euch an Wuchs mehrte»."),
"prophets_159": ("Womit wurde das Volk 'Ad laut Sure Al-Haqqa vernichtet?", ["Mit einem eisigen, brausenden Wind", "Mit einer Sintflut", "Mit einem Erdbeben", "Mit einer Heuschreckenplage"], "«Was aber 'Ad angeht, so wurden sie durch einen eiskalten, gewaltigen Wind vernichtet»."),
"prophets_160": ("Was warf Hud seinem Volk vor, das auf jeder Anhöhe baute?", ["Aus Eitelkeit zu bauen und ewig bleiben zu wollen", "Das Land zu bebauen", "Fernhandel zu treiben", "Bei Nacht zu reisen"], "«Baut ihr auf jeder Anhöhe ein Wahrzeichen zum Zeitvertreib? Und nehmt ihr euch Schlösser, als würdet ihr ewig leben?»"),
"prophets_161": ("Was machte Thamud laut Koran mit den Bergen?", ["Sie hauten sich Häuser hinein", "Sie versteckten Gold darin", "Sie weideten Herden darauf", "Sie mieden sie"], "«Ihr nehmt euch Schlösser in seinen Ebenen und haut Häuser in die Berge»."),
"prophets_162": ("Als was wurde die Kamelstute laut Sure Al-Qamar zu Thamud gesandt?", ["Als Prüfung für sie", "Als Belohnung", "Als Geschenk ihres Königs", "Als Herde zum Verkauf"], "«Wir senden die Kamelstute als Prüfung für sie: so beobachte sie und sei geduldig»."),
"prophets_163": ("Was ergriff Thamud, nachdem sie die Kamelstute getötet hatten?", ["Das Beben (ar-rajfa)", "Die Sintflut", "Der eisige Wind", "Die Hungersnot"], "«Da ergriff sie das Beben, und am Morgen lagen sie in ihren Häusern auf dem Boden»."),
"prophets_164": ("Welcher Prophet wurde zu dem Volk gesandt, das die große Schändlichkeit beging, und sprach: «Wollt ihr nicht gottesfürchtig sein?»", ["Lut (Lot)", "Salih", "Hud", "Shu'ayb"], "«Als ihr Bruder Lut zu ihnen sagte: “Wollt ihr nicht gottesfürchtig sein?”»"),
"prophets_165": ("Was wurde Lut in der Nacht der Strafe befohlen?", ["Nachts mit seiner Familie fortzuziehen und sich nicht umzuwenden", "Sein Volk zu versammeln", "Die Morgendämmerung abzuwarten", "Sich im Berg zu verstecken"], "«So zieh mit deiner Familie in einem Teil der Nacht fort, und keiner von euch soll sich umwenden»."),
"prophets_166": ("Welcher Prophet wurde zum Volk von Madyan gesandt, das bei Maß und Gewicht betrog?", ["Shu'ayb", "Lut (Lot)", "Hud", "Ilyas (Elia)"], "Shu'ayb befahl ihnen, volles Maß und gerechtes Gewicht zu geben und auf der Erde kein Unheil zu stiften."),
"prophets_167": ("Was sagte Shu'ayb seinem Volk darüber, was er wirklich wollte?", ["«Ich will nur die Besserung, soweit ich kann»", "«Ich will nur Reichtum»", "«Ich will herrschen»", "«Ich will fortgehen»"], "«Ich will nur die Besserung, soweit ich kann. Und mein Gelingen hängt allein von Allah ab»."),
"prophets_168": ("Was sagte Allah zu Ibrahim, nachdem Er ihn mit Geboten geprüft hatte, die er erfüllte?", ["«Ich mache dich zu einem Vorbild (Imam) für die Menschen»", "«Ich gebe dir ein Königreich»", "«Ich mache dich reich»", "«Ich mache dich zum König von Babylon»"], "«Ich mache dich zu einem Vorbild für die Menschen». Ibrahim fragte: «Und von meiner Nachkommenschaft?»"),
"prophets_169": ("Wie brachte Ibrahim den König zum Schweigen, der behauptete, Leben und Tod zu geben?", ["«Allah bringt die Sonne vom Osten: so bring du sie vom Westen»", "«Lass Regen fallen»", "«Versetze diesen Berg»", "«Zähle die Sterne»"], "«Allah bringt die Sonne vom Osten; so bring du sie vom Westen». Da war der Ungläubige verblüfft."),
"prophets_170": ("Was wurde Ibrahim befohlen, den Menschen über das Heilige Haus auszurufen?", ["Die Pilgerfahrt: sie werden zu Fuß und auf jedem Reittier kommen", "Den Handel", "Den Krieg", "Das Schweigen"], "«Und rufe unter den Menschen die Pilgerfahrt aus: sie werden zu dir kommen zu Fuß und auf jedem hageren Reittier»."),
"prophets_171": ("Was setzte Ibrahim seinen geehrten Gästen vor, die es nicht anrührten?", ["Ein gebratenes Mastkalb", "Brot und Wasser", "Datteln", "Milch"], "Er ging zu den Seinen und brachte ein Mastkalb; als er sah, dass ihre Hände es nicht berührten, empfand er Furcht."),
"prophets_172": ("Von wem sagt der Koran, er sei «ein schönes Vorbild» (uswa hasana) für die Gläubigen, samt denen, die mit ihm waren?", ["Ibrahim (Abraham)", "Nuh (Noah)", "Musa (Moses)", "Dawud (David)"], "«Ihr habt ein schönes Vorbild in Ibrahim und denen, die mit ihm waren»."),
"prophets_173": ("Worum bat Ibrahim in der Sure Ibrahim für die Stadt Mekka?", ["Dass sie sicher sei und er und seine Söhne vom Götzendienst bewahrt blieben", "Dass sie ein großer Markt werde", "Dass sie Paläste habe", "Dass sie leer bleibe"], "«Mein Herr, mache diese Stadt sicher und bewahre mich und meine Söhne davor, Götzen zu dienen»."),
"prophets_174": ("Was sagte Ibrahim, als er sein Volk verließ?", ["«Ich gehe zu meinem Herrn: Er wird mich rechtleiten»", "«Ich gehe, mein Glück zu suchen»", "«Ich kehre zurück, um sie zu bekämpfen»", "«Ich gehe nach Ägypten»"], "«Ich gehe zu meinem Herrn: Er wird mich rechtleiten»."),
"prophets_175": ("Von welchem Propheten sagt der Koran, er sei «treu in seinem Versprechen» gewesen und habe den Seinen Gebet und Zakat geboten?", ["Isma'il (Ismael)", "Ishaq (Isaak)", "Ya'qub (Jakob)", "Yusuf (Josef)"], "«Er war treu in seinem Versprechen; er war ein Gesandter und ein Prophet. Er pflegte seiner Familie Gebet und Zakat zu gebieten»."),
"prophets_176": ("Was riet Ya'qub dem Yusuf nach dessen Traum?", ["Ihn seinen Brüdern nicht zu erzählen", "Ihn allen zu erzählen", "Ihn aufzuschreiben", "Ihn zu vergessen"], "«O mein Sohn, erzähle dein Traumgesicht nicht deinen Brüdern, sonst schmieden sie eine List gegen dich»."),
"prophets_177": ("Welches Indiz erwies Yusufs Unschuld vor dem Hausherrn?", ["Sein von hinten zerrissenes Hemd", "Ein versteckter Zeuge", "Ein Brief", "Ein Eid"], "War das Hemd von hinten zerrissen, so hat sie gelogen und er gehört zu den Wahrhaftigen."),
"prophets_178": ("Was taten die Frauen der Stadt, als sie Yusuf sahen?", ["Sie schnitten sich vor Bewunderung in die Hände", "Sie flohen", "Sie schwiegen", "Sie lachten"], "«Als sie ihn sahen, priesen sie ihn und schnitten sich in die Hände und sagten: “Das ist kein Mensch, das ist nur ein edler Engel!”»"),
"prophets_179": ("Was lehrte Yusuf seine beiden Gefängnisgefährten, bevor er ihre Träume deutete?", ["Die Einheit Allahs, und dass das Urteil allein Ihm gehört", "Die Medizin", "Die Berechnung der Ernten", "Die Dichtkunst"], "«Sind getrennte Herren besser oder Allah, der Eine, der Allbezwinger? … Das Urteil gehört allein Allah»."),
"prophets_180": ("Was sagte der König von Ägypten zu Yusuf, nachdem er mit ihm gesprochen hatte?", ["«Heute bist du bei uns in fester Stellung und vertrauenswürdig»", "«Kehre ins Gefängnis zurück»", "«Verlasse Ägypten»", "«Ich gebe dir meine Tochter»"], "«Als er mit ihm gesprochen hatte, sagte er: “Du bist heute bei uns in fester Stellung und vertrauenswürdig”»."),
"prophets_181": ("Wie behielt Yusuf seinen Bruder bei sich?", ["Der Becher des Königs fand sich im Gepäck seines Bruders", "Er kaufte ihn", "Er sperrte ihn grundlos ein", "Er machte ihn zum Minister"], "«So gaben Wir Yusuf diese List ein»: der Becher kam aus dem Sack seines Bruders."),
"prophets_182": ("Was sagte Yusuf zu seinen Brüdern, als sie ihre Schuld eingestanden?", ["«Heute trifft euch kein Vorwurf»", "«Ihr werdet bestraft»", "«Geht und kommt nicht wieder»", "«Ich habe euch vergessen»"], "«Heute trifft euch kein Vorwurf. Möge Allah euch vergeben: Er ist der Barmherzigste der Barmherzigen»."),
"prophets_183": ("Was sagte Ya'qub seinen Söhnen über die Verzweiflung?", ["«Verzweifelt nicht an der Barmherzigkeit Allahs»", "«Zieht nie wieder fort»", "«Sprecht mit niemandem»", "«Schreibt nichts auf»"], "«Und verzweifelt nicht am Trost Allahs: an Allahs Trost verzweifelt nur das ungläubige Volk»."),
"prophets_184": ("Welches Bittgebet sprach Yusuf am Ende seiner Geschichte?", ["Als Gottergebener zu sterben und den Rechtschaffenen angeschlossen zu werden", "Über ganz Ägypten zu herrschen", "Nach Kanaan zurückzukehren", "Lange zu leben"], "«Lass mich als Gottergebenen sterben und schließe mich den Rechtschaffenen an»."),
"prophets_185": ("Wie wandte sich Ayyub in der Prüfung an seinen Herrn?", ["«Mich hat Unheil getroffen, und Du bist der Barmherzigste»", "«Warum ich?»", "«Gib mir meinen Reichtum zurück»", "«Vernichte meine Feinde»"], "«Und gedenke Unseres Dieners Ayyub, als er zu seinem Herrn rief: “Der Satan hat mir Mühsal und Pein zugefügt”»."),
"prophets_186": ("Was gab Allah Ayyub nach der Prüfung zurück, laut Sure Sad?", ["Seine Familie, und noch einmal so viele dazu", "Ein Königreich", "Ein Schiff", "Eine Kamelherde"], "«Und Wir gaben ihm seine Familie und noch einmal so viele dazu, aus Barmherzigkeit von Uns und als Ermahnung für die Verständigen»."),
"prophets_187": ("Was rettete Yunus laut Sure As-Saffat davor, im Bauch des Fisches zu bleiben?", ["Dass er zu denen gehörte, die Allah preisen", "Seine Kraft", "Ein vorbeifahrendes Schiff", "Ein günstiger Wind"], "«Wäre er nicht einer von denen gewesen, die preisen, so wäre er in seinem Bauch geblieben bis zum Tag der Auferweckung»."),
"prophets_188": ("Welches Volk glaubte laut Koran, bevor die Strafe es erreichte, und es nützte ihm?", ["Das Volk des Yunus (Jona)", "Das Volk Nuhs", "Das Volk Luts", "Das Volk Huds"], "«Hätte es doch eine Stadt gegeben, die glaubte und der ihr Glaube nützte – außer dem Volk des Yunus!»"),
"prophets_189": ("Wie nennt der Koran Yunus, als dem Propheten ﷺ geboten wird, in der Ungeduld nicht wie er zu sein?", ["«Der Gefährte des Fisches» (sahib al-hut)", "«Der Mann mit dem Stab»", "«Der Mann des Berges»", "«Der Mann am Brunnen»"], "«Und sei nicht wie der Gefährte des Fisches, als er rief, während er bedrängt war»."),
"prophets_190": ("Welcher Prophet tadelte sein Volk, Ba'l anzurufen und den besten der Schöpfer zu verlassen?", ["Ilyas (Elia)", "Al-Yasa' (Elisa)", "Yunus (Jona)", "Shu'ayb"], "«Und Ilyas gehörte wahrlich zu den Gesandten… “Ruft ihr Ba'l an und verlasst den besten der Schöpfer?”»"),
"prophets_191": ("Welchen Propheten nennt der Koran neben Isma'il und Idris unter den Standhaften, die Allah in Seine Barmherzigkeit aufnahm?", ["Dhul-Kifl", "Ilyas (Elia)", "Yunus (Jona)", "Al-Yasa' (Elisa)"], "«Und Isma'il, Idris und Dhul-Kifl: alle gehörten zu den Standhaften. Und Wir nahmen sie in Unsere Barmherzigkeit auf»."),
"prophets_192": ("Was tat Allah für die Kinder Israels am Meer, als der Pharao sie verfolgte?", ["Er spaltete das Meer und rettete sie", "Er ließ die Nacht hereinbrechen", "Er sandte Schiffe", "Er trocknete das Meer für immer aus"], "«Und als Wir für euch das Meer spalteten: Wir retteten euch und ertränkten die Leute des Pharaos»."),
"prophets_193": ("Warum bat Musa Allah, Harun mit ihm zu senden?", ["Weil er beredter war als er", "Weil er älter war", "Weil er Ägypten kannte", "Weil er schreiben konnte"], "«Und mein Bruder Harun ist beredter als ich: so sende ihn mit mir als Beistand, der mich bestätigt»."),
"prophets_194": ("Wie sollten Musa und Harun zum Pharao sprechen?", ["Mit sanften Worten", "Mit Drohungen", "Ohne ihn anzusehen", "Nur schriftlich"], "«Und sprecht zu ihm mit sanften Worten: vielleicht lässt er sich ermahnen oder fürchtet sich»."),
"prophets_195": ("Wer aus dem Haus des Pharaos verteidigte Musa und verbarg dabei seinen Glauben?", ["Ein gläubiger Mann aus der Familie des Pharaos", "Der Hohepriester", "Der Heerführer", "Der Wesir Haman"], "«Und ein gläubiger Mann aus der Familie des Pharaos, der seinen Glauben verbarg, sagte: “Wollt ihr einen Mann töten, weil er sagt: Mein Herr ist Allah?”»"),
"prophets_196": ("Was sagte Harun seinem Volk während Musas Abwesenheit?", ["Dass sie nur mit dem Kalb geprüft würden und ihm folgen sollten", "Dass sie das Kalb behalten sollten", "Dass sie nach Ägypten ziehen sollten", "Dass sie schweigen sollten"], "«O mein Volk, ihr werdet damit nur geprüft. Euer Herr ist der Allerbarmer: so folgt mir»."),
"prophets_197": ("Was sagte die Frau des Pharaos, als sie den Säugling Musa fand?", ["«Er wird eine Freude für mein und dein Auge sein: tötet ihn nicht»", "«Gebt ihn seiner Mutter zurück»", "«Bringt ihn zum Fluss»", "«Verkauft ihn»"], "«Und die Frau des Pharaos sagte: “Eine Freude des Auges für mich und für dich. Tötet ihn nicht: vielleicht nützt er uns”»."),
"prophets_198": ("Wie bat Musa darum, dem wissenden Diener (al-Khidr) zu folgen?", ["«Darf ich dir folgen, unter der Bedingung, dass du mich lehrst?»", "«Befiehl mir und ich gehorche»", "«Lehre mich gegen Bezahlung»", "«Komm mit mir»"], "«Darf ich dir folgen unter der Bedingung, dass du mich von dem lehrst, was dir an Rechtleitung gelehrt wurde?»"),
"prophets_199": ("In welchem Zustand kehrte Musa zu seinem Volk zurück, nachdem er das Kalb gesehen hatte?", ["Zornig und betrübt", "Freudig", "Schweigend", "Gleichgültig"], "«Und als Musa zu seinem Volk zurückkehrte, zornig und betrübt… warf er die Tafeln hin»."),
"prophets_200": ("Welche Botschaft sollte Musa laut Sure An-Nazi'at dem Pharao bringen?", ["«Möchtest du dich läutern, und dass ich dich zu deinem Herrn rechtleite?»", "«Gib mir mein Volk zurück»", "«Baue mir einen Palast»", "«Verlasse Ägypten»"], "«Geh zum Pharao: er hat das Maß überschritten. Und sag: Möchtest du dich läutern, und dass ich dich zu deinem Herrn rechtleite, damit du Ihn fürchtest?»"),
"prophets_201": ("Wer pries Allah zusammen mit Dawud, am Abend und am Morgen?", ["Die Berge und die Vögel", "Die Flüsse", "Die Sterne", "Die Winde"], "«Wir machten die Berge dienstbar, dass sie mit ihm preisen am Abend und bei Sonnenaufgang, und die versammelten Vögel»."),
"prophets_202": ("Was gab Allah dem Dawud laut Koran neben einem gefestigten Königreich?", ["Die Weisheit und die entscheidende Rede", "Riesige Heere", "Gold und Silber", "Einen Elfenbeinpalast"], "«Und Wir festigten seine Herrschaft und gaben ihm die Weisheit und die Entscheidung der Rede»."),
"prophets_203": ("Was wurde Dawud beim Anfertigen der Panzerhemden befohlen?", ["Die Ringe richtig zu bemessen", "Seinen Namen einzugravieren", "Sie zu vergolden", "Sie zu verkaufen"], "«Fertige vollständige Panzerhemden an und bemiss die Ringe richtig»."),
"prophets_204": ("Was sagten Dawud und Sulaiman, als Allah ihnen Wissen gab?", ["«Lob sei Allah, der uns vor vielen Seiner gläubigen Diener bevorzugt hat»", "«Wir sind die Besten»", "«Niemand gleicht uns»", "«Wir haben es verdient»"], "«Lob sei Allah, der uns vor vielen Seiner gläubigen Diener bevorzugt hat»."),
"prophets_205": ("Was tat Sulaiman, als er die Ameise ihr Volk warnen hörte?", ["Er lächelte und bat Allah, ihn dankbar zu machen", "Er wurde zornig", "Er lenkte sein Heer schweigend ab", "Er befahl Schweigen"], "«Da lächelte er über ihre Worte und sagte: “Mein Herr, gib mir ein, für Deine Gunst dankbar zu sein”»."),
"prophets_206": ("Welche Nachricht brachte der Wiedehopf zu Sulaiman?", ["Dass eine Frau über Saba herrschte und ihr Volk sich vor der Sonne niederwarf", "Dass ein Heer nahte", "Dass eine Dürre herrschte", "Dass ein Schatz verborgen lag"], "«Ich komme zu dir aus Saba mit einer sicheren Nachricht: ich fand eine Frau, die über sie herrscht… sie werfen sich vor der Sonne nieder»."),
"prophets_207": ("Was erstaunte die Königin von Saba beim Betreten des Palastes Sulaimans?", ["Der Boden aus Glas, den sie für Wasser hielt", "Ein gezähmter Löwe", "Ein hängender Garten", "Ein goldener Thron"], "«Es wurde zu ihr gesagt: “Tritt in den Palast ein”. Als sie ihn sah, hielt sie ihn für tiefes Wasser und entblößte ihre Beine. Er sagte: “Es ist ein mit Glas ausgelegter Palast”»."),
"prophets_208": ("Woraus bestanden Sulaimans Heere laut Koran?", ["Aus Dschinn, Menschen und Vögeln", "Nur aus Reitern", "Aus Seeleuten", "Nur aus Bogenschützen"], "«Und für Sulaiman wurden seine Heere aus Dschinn, Menschen und Vögeln versammelt, in Reihen geordnet»."),
"prophets_209": ("Wie beschrieb Zakariyya seinen Zustand, als er seinen Herrn anrief?", ["«Mein Gebein ist schwach geworden und mein Haupt ergraut»", "«Ich bin reich und satt»", "«Ich bin fern von meinem Volk»", "«Ich bin auf Reisen»"], "«Mein Herr, mein Gebein ist schwach geworden und mein Haupt ergraut, und nie war ich unglücklich in meinem Bittgebet zu Dir»."),
"prophets_210": ("Welches Zeichen wurde Zakariyya für die Geburt Yahyas gegeben?", ["Drei Tage lang nur durch Gesten zu den Menschen zu sprechen", "Ein Stern", "Regen außerhalb der Jahreszeit", "Ein wiederkehrender Traum"], "«Dein Zeichen ist, dass du drei Tage lang nicht zu den Menschen sprechen wirst, außer durch Gesten»."),
"prophets_211": ("Was wurde Yahya bezüglich des Buches gesagt?", ["«Nimm das Buch mit Kraft»", "«Verbirg das Buch»", "«Kopiere das Buch»", "«Lies es einmal»"], "«O Yahya, nimm das Buch mit Entschlossenheit!» Und Wir gaben ihm die Urteilskraft schon als Kind."),
"prophets_212": ("Was befahlen die Engel Maryam, nachdem sie ihr ihre Erwählung verkündet hatten?", ["Ihrem Herrn demütig zu dienen, sich niederzuwerfen und sich zu verneigen", "Eine Reise anzutreten", "Für immer zu schweigen", "Im Tempel zu lehren"], "«O Maryam, sei deinem Herrn demütig ergeben, wirf dich nieder und verneige dich mit denen, die sich verneigen»."),
"prophets_213": ("Was sollte Maryam bei der Geburt schütteln, um zu essen?", ["Den Stamm der Palme, damit frische Datteln fielen", "Einen Olivenbaum", "Einen Feigenbaum", "Einen Weinstock"], "«Und schüttle den Stamm der Palme zu dir hin: er lässt frische, reife Datteln auf dich fallen»."),
"prophets_214": ("Was sagte 'Isa in der Wiege über das, was Allah ihm auftrug?", ["Das Gebet und die Zakat, solange er lebt", "Den Handel", "Das Schweigen", "Die Reise"], "«Und Er hat mir das Gebet und die Zakat aufgetragen, solange ich lebe»."),
"prophets_215": ("Wie beschreibt die Sure Az-Zukhruf 'Isa, den Sohn Maryams?", ["Ein Diener, dem Allah Gunst erwies und den Er zum Beispiel für die Kinder Israels machte", "Ein König Israels", "Ein herabgesandter Engel", "Ein Schreiber des Tempels"], "«Er war nur ein Diener, dem Wir Gunst erwiesen und den Wir zu einem Beispiel für die Kinder Israels machten»."),
"prophets_216": ("Was wird 'Isa am Tag der Auferstehung antworten, wenn Allah ihn befragt?", ["«Preis sei Dir! Es steht mir nicht zu, zu sagen, wozu ich kein Recht habe»", "«Ich erinnere mich nicht»", "«Sie haben es geschrieben»", "«Frage die Jünger»"], "«Preis sei Dir! Es steht mir nicht zu, zu sagen, wozu ich kein Recht habe»."),
"prophets_217": ("Wie beschreibt der Koran 'Isa, den Sohn Maryams?", ["Der Gesandte Allahs, Sein Wort, das Er Maryam entbot, und ein Geist von Ihm", "Ein gesandter Engel", "Ein gerechter König", "Ein gelehrter Schreiber"], "«Der Messias 'Isa, der Sohn Maryams, ist nur der Gesandte Allahs und Sein Wort, das Er Maryam entbot, und ein Geist von Ihm»."),
"prophets_218": ("An welche Gaben erinnert Allah in der Sure Ad-Duha Seinen Propheten ﷺ?", ["Er nahm ihn als Waise auf, leitete ihn recht und machte ihn reich", "Er gab ihm ein Königreich", "Er gab ihm ein Heer", "Er gab ihm einen Palast"], "«Fand Er dich nicht als Waise und gab dir Zuflucht? Und fand dich irrend und leitete dich recht? Und fand dich arm und machte dich reich?»"),
"prophets_219": ("Welches Versprechen wiederholt die Sure Ash-Sharh zweimal?", ["«Mit der Schwierigkeit kommt die Erleichterung»", "«Der Sieg ist nah»", "«Das Paradies ist verheißen»", "«Die Feinde werden untergehen»"], "«Denn mit der Schwierigkeit kommt Erleichterung. Mit der Schwierigkeit kommt Erleichterung»."),
"prophets_220": ("Was wurde dem Propheten ﷺ in der Sure Al-Kawthar gegeben, und was wurde ihm dafür geboten?", ["Al-Kawthar; zu seinem Herrn zu beten und zu opfern", "Ein Heer; zu kämpfen", "Ein Königreich; zu herrschen", "Ein Schatz; ihn zu verteilen"], "«Wir haben dir al-Kawthar gegeben. So bete zu deinem Herrn und opfere»."),
"prophets_221": ("Wie beschreibt die Sure At-Tawba den Gesandten ﷺ gegenüber den Gläubigen?", ["Besorgt um sie, mitfühlend und barmherzig", "Hart und distanziert", "Reich und mächtig", "Schweigsam und zurückgezogen"], "«Zu euch ist ein Gesandter aus euren eigenen Reihen gekommen… besorgt um euch, zu den Gläubigen mitfühlend und barmherzig»."),
"prophets_222": ("Was hätte die Menschen laut Koran vom Propheten ﷺ vertrieben, wäre er so gewesen?", ["Wäre er grob und hartherzig gewesen", "Wäre er reich gewesen", "Wäre er jung gewesen", "Wäre er schweigsam gewesen"], "«Durch eine Barmherzigkeit von Allah warst du milde zu ihnen. Wärst du grob und hartherzig gewesen, hätten sie sich aus deiner Umgebung fortbegeben»."),
"prophets_223": ("Was sagt der Koran über den Gesandten Allahs ﷺ für jene, die auf Allah und den Jüngsten Tag hoffen?", ["Er ist für sie ein schönes Vorbild", "Er ist ein König", "Er ist ein Richter", "Er ist ein Karawanenführer"], "«Ihr habt im Gesandten Allahs ein schönes Vorbild für jeden, der auf Allah und den Jüngsten Tag hofft»."),
"prophets_224": ("Zu wem wurde der Prophet Muhammad ﷺ laut Sure Saba gesandt?", ["Zur ganzen Menschheit", "Nur zu den Quraisch", "Nur zu den Arabern", "Zu den Leuten von Medina"], "«Und Wir haben dich nur als Verkünder froher Botschaft und als Warner für die ganze Menschheit gesandt»."),
"prophets_225": ("Welchen Vers rezitierte der Prophet ﷺ, als die Götzen um die Kaaba entfernt wurden?", ["«Die Wahrheit ist gekommen und das Falsche ist geschwunden»", "«Wir haben dir einen deutlichen Sieg gegeben»", "«Sprich: Er ist Allah, ein Einziger»", "«Wenn Allahs Hilfe kommt»"], "«Und sag: Die Wahrheit ist gekommen und das Falsche ist geschwunden; das Falsche muss ja schwinden»."),
"prophets_226": ("Was sagen die Gläubigen über die Gesandten Allahs am Ende der Sure Al-Baqara?", ["«Wir machen keinen Unterschied zwischen Seinen Gesandten»", "«Wir folgen nur dem letzten»", "«Wir bevorzugen einen»", "«Wir übergehen sie»"], "«Wir machen keinen Unterschied zwischen Seinen Gesandten. Und sie sagten: Wir hören und gehorchen»."),
"prophets_227": ("Welche gemeinsame Botschaft brachte jeder Gesandte seinem Volk?", ["«Dient Allah und meidet die falschen Götter»", "«Baut Tempel»", "«Werdet reich»", "«Schreibt Bücher»"], "«Und Wir haben in jeder Gemeinschaft einen Gesandten erweckt: Dient Allah und meidet den Taghut»."),
"prophets_228": ("In welcher Sprache wurde jeder Gesandte laut Sure Ibrahim gesandt?", ["In der Sprache seines Volkes, um ihnen klarzumachen", "Nur auf Arabisch", "Auf Hebräisch", "In einer himmlischen Sprache"], "«Und Wir haben keinen Gesandten gesandt außer in der Sprache seines Volkes, damit er ihnen klarmache»."),
"prophets_229": ("Was wurde jedem Gesandten vor Muhammad ﷺ laut Sure Al-Anbiya offenbart?", ["Dass es keinen Gott gibt außer Ihm: so dient Ihm", "Ein Heiligtum zu bauen", "Länder zu erobern", "Es geheim zu halten"], "«Und Wir sandten vor dir keinen Gesandten, dem Wir nicht eingegeben hätten: Es gibt keinen Gott außer Mir, so dient Mir»."),
"prophets_230": ("Welche Gruppe von Propheten wird in der Sure Al-An'am als die rechtgeleitete Nachkommenschaft Ibrahims aufgezählt?", ["Dawud, Sulaiman, Ayyub, Yusuf, Musa und Harun unter anderen", "Nur Musa und 'Isa", "Nur Isma'il und Ishaq", "Nur Nuh und Hud"], "Die Stelle zählt eine lange Reihe von Propheten auf, die Allah rechtleitete, und sagt: «So vergelten Wir den Gutes Tuenden»."),
"prophets_231": ("Was sagt der Koran über die Gesandten im Verhältnis zueinander?", ["Allah hat einige von ihnen vor anderen bevorzugt", "Sie sind alle im Rang gleich", "Nur der letzte zählt", "Sie wussten nichts voneinander"], "«Diese Gesandten: einige von ihnen haben Wir vor anderen bevorzugt»."),
"prophets_232": ("Welchen Bund nahm Allah laut Sure Al 'Imran von den Propheten?", ["An den Gesandten zu glauben, der bestätigend käme, und ihm beizustehen", "Ihr Volk nie zu verlassen", "Jeder einen Tempel zu bauen", "Jeder ein Buch zu schreiben"], "«Wenn zu euch ein Gesandter kommt, der bestätigt, was bei euch ist, dann müsst ihr an ihn glauben und ihm beistehen»."),
"prophets_233": ("Welche Propheten nennt der Koran, wenn er sagt, Allah habe ihnen dieselbe Religion vorgeschrieben?", ["Nuh, Ibrahim, Musa und 'Isa, samt dem dem Propheten ﷺ Offenbarten", "Nur Adam und Idris", "Nur Dawud und Sulaiman", "Nur Hud und Salih"], "«Er hat euch von der Religion festgelegt, was Er Nuh anbefahl, und was Wir dir offenbart haben, und was Wir Ibrahim, Musa und 'Isa anbefahlen»."),
"prophets_234": ("Was sagt der Koran über die Gesandten, deren Geschichte er nicht erzählt?", ["Es gibt solche, deren Geschichte Allah dem Propheten ﷺ nicht erzählt hat", "Sie existieren nicht", "Alle sind namentlich genannt", "Sie sind unwichtig"], "«Von ihnen haben Wir dir von einigen berichtet, und von anderen haben Wir dir nicht berichtet»."),
"prophets_235": ("Aus welchen Menschen erwählte Allah laut Sure Yusuf alle Seine Gesandten?", ["Aus Männern der Städte, denen Er offenbarte", "Aus den Engeln", "Aus den Königen", "Nur aus Wüstenbewohnern"], "«Und Wir sandten vor dir nur Männer aus den Bewohnern der Städte, denen Wir offenbarten»."),
"prophets_236": ("Woran erinnert der Koran bezüglich der vor Muhammad ﷺ der Lüge bezichtigten Gesandten?", ["Sie waren geduldig, bis Unsere Hilfe zu ihnen kam", "Sie gaben auf", "Sie versteckten sich", "Sie änderten ihre Botschaft"], "«Schon vor dir wurden Gesandte der Lüge bezichtigt, doch sie ertrugen es geduldig, bis Unsere Hilfe zu ihnen kam»."),
"prophets_237": ("Welche Familien erwählte Allah laut Sure Al 'Imran vor den Weltenbewohnern?", ["Adam, Nuh, die Familie Ibrahims und die Familie 'Imrans", "Die Könige Ägyptens", "Die Stämme Medinas", "Die Leute von Saba"], "«Gewiss, Allah hat Adam, Nuh, die Familie Ibrahims und die Familie 'Imrans vor den Weltenbewohnern erwählt»."),
"prophets_238": ("An welche Gnaden erinnerte Musa sein Volk, als er sie einlud, das Heilige Land zu betreten?", ["Dass Allah Propheten unter ihnen bestellte und sie zu Königen machte", "Dass Er ihnen Schiffe gab", "Dass Er ihnen Gold gab", "Dass Er ihnen Pferde gab"], "«O mein Volk, gedenkt der Gnade Allahs an euch: Er bestellte Propheten unter euch und machte euch zu Königen»."),
"prophets_239": ("Wie beschrieben die Tora und das Evangelium laut Koran den schriftunkundigen Propheten?", ["Er gebietet das Rechte, verbietet das Verwerfliche und nimmt ihnen ihre Lasten ab", "Er bringt Reichtum", "Er herrscht mit Gewalt", "Er baut Tempel"], "«…den schriftunkundigen Propheten, den sie bei sich in der Tora und im Evangelium aufgeschrieben finden: er gebietet ihnen das Rechte und verbietet das Verwerfliche… und nimmt ihnen ihre Last ab»."),
"prophets_240": ("Auf wen sagte Nuh sich zu stützen, als er sein Volk herausforderte, Ränke zu schmieden?", ["Auf Allah, auf den er vertraute", "Auf seine Söhne", "Auf seinen Stamm", "Auf sein Schiff"], "«Auf Allah verlasse ich mich. So einigt euch, ihr und eure Teilhaber»."),
"prophets_241": ("Wem schreibt Ibrahim in seinem Bittgebet die Heilung zu, wenn er krank ist?", ["Allah allein", "Den Ärzten", "Den Kräutern", "Der Zeit"], "«Und wenn ich krank bin, ist Er es, der mich heilt», sagte Ibrahim, seinen Herrn beschreibend."),
"prophets_242": ("Womit wurde Ibrahims Sohn laut Sure As-Saffat losgekauft?", ["Mit einem großartigen Opfer", "Mit einem Lösegeld aus Gold", "Mit einer Karawane", "Mit einer ganzen Herde"], "«Und Wir lösten ihn mit einem großartigen Opfer aus»."),
"prophets_243": ("Woran erklären die Gläubigen zu glauben im Vers «Sagt: Wir glauben an Allah…»?", ["An das Ibrahim, Isma'il, Ishaq, Ya'qub, Musa, 'Isa und den Propheten Offenbarte", "An ein einziges Buch", "An einen einzigen Propheten", "An ihre eigenen Überlieferungen"], "«Sagt: Wir glauben an Allah und an das, was zu uns herabgesandt wurde, und an das, was zu Ibrahim, Isma'il, Ishaq, Ya'qub herabgesandt wurde…»"),
"prophets_244": ("Warum erzählt Allah dem Propheten ﷺ die Berichte der Gesandten?", ["Um sein Herz zu festigen", "Um ihn zu beschäftigen", "Um ihn Geschichte zu lehren", "Um ihn zu zerstreuen"], "«Und alles erzählen Wir dir von den Berichten der Gesandten, um dein Herz damit zu festigen»."),
"prophets_245": ("Was sollte der Prophet ﷺ am Ende der Sure Al-Kahf über sich selbst sagen?", ["«Ich bin nur ein Mensch wie ihr; mir wurde offenbart, dass euer Gott ein einziger Gott ist»", "«Ich bin ein König»", "«Ich bin ein Engel»", "«Ich kenne das Verborgene»"], "«Sag: Ich bin nur ein Mensch wie ihr; mir wird offenbart, dass euer Gott ein einziger Gott ist»."),
"prophets_246": ("Wie beschreibt die Sure Al-Fath jene, die mit dem Gesandten ﷺ sind?", ["Hart gegen die Ungläubigen, barmherzig untereinander", "Reich und zahlreich", "Schweigsam und zurückgezogen", "Reisende und Händler"], "«Muhammad ist der Gesandte Allahs. Und diejenigen, die mit ihm sind, sind hart gegen die Ungläubigen, barmherzig untereinander»."),
"prophets_247": ("Was sagt die Sure An-Najm über das Wort des Propheten ﷺ?", ["Er spricht nicht aus Neigung: es ist nur eine eingegebene Offenbarung", "Er spricht als Dichter", "Er spricht als Wahrsager", "Er spricht aus sich selbst"], "«Euer Gefährte ist nicht abgeirrt und nicht in die Irre gegangen; und er spricht nicht aus Neigung. Es ist nur eine Offenbarung, die eingegeben wird»."),
"prophets_248": ("Was wurde dem Propheten ﷺ geboten, als Allahs Hilfe und der Sieg kamen?", ["Seinen Herrn lobpreisend zu preisen und Ihn um Vergebung zu bitten", "Mit einem Festmahl zu feiern", "Ein Denkmal zu errichten", "Auszuruhen"], "«Wenn Allahs Hilfe und der Sieg kommen… dann lobpreise deinen Herrn und bitte Ihn um Vergebung»."),
"prophets_249": ("Welche drei Aufgaben schreibt die Sure Al-Jumu'a dem zu den Schriftunkundigen gesandten Gesandten zu?", ["Ihnen die Verse zu verlesen, sie zu läutern und sie das Buch und die Weisheit zu lehren", "Bauen, handeln und herrschen", "Schreiben, rechnen und reisen", "Richten, strafen und Steuern erheben"], "«Er ist es, der unter den Schriftunkundigen einen Gesandten aus ihren eigenen Reihen erweckt hat, der ihnen Seine Verse verliest, sie läutert und sie das Buch und die Weisheit lehrt»."),
"prophets_250": ("Welchen Schutz erwähnt der Koran, solange der Prophet ﷺ unter ihnen war?", ["Allah würde sie nicht strafen, solange er unter ihnen war", "Sie wären reich", "Sie würden immer siegen", "Sie würden nicht sterben"], "«Aber Allah würde sie nicht strafen, während du unter ihnen bist»."),
}
